#include <iostream>
#include <type_traits>
#include <concepts>

template<typename T>
void process(T value) {
    if constexpr (std::integral<T>) {
        std::cout << "Processing an integer: " << value << "\n";
    } else if constexpr (std::floating_point<T>) {
        std::cout << "Processing a floating point number: " << value << "\n";
    } else {
        static_assert(sizeof(T) == 0, "Unsupported type");
    }
}

int main() {
    process(42);           // integer
    process(3.14);         // floating-point
    // process("string"); // Uncommenting this will trigger the static_assert
}

#include <iostream>
#include <type_traits>

// SFINAE for enabling function only when T is a pointer type
template<typename T, typename = void>
struct is_pointer_type : std::false_type {};

template<typename T>
struct is_pointer_type<T, std::enable_if_t<std::is_pointer<T>::value>> : std::true_type {};

template<typename T>
void foo(T value) {
    if constexpr (is_pointer_type<T>::value) {
        std::cout << "Pointer type: " << value << "\n";
    } else {
        std::cout << "Non-pointer type\n";
    }
}

int main() {
    int a = 5;
    foo(&a);  // Pointer type
    foo(a);   // Non-pointer type
}
